using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
JsonTypeInfo<WeatherForecast> typeInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> returned type: {typeInfo.Type.Name}");

var forecast = new WeatherForecast("Seattle", 62);
string json = JsonSerializer.Serialize(forecast, typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---

// 2a. Type that IS resolvable
if (options.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? resolved))
{
    Console.WriteLine($"TryGetTypeInfo<WeatherForecast> succeeded – type: {resolved!.Type.Name}");
}

// 2b. Source-gen-only options with NO resolver → type is NOT resolvable
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonSerializer.IsReflectionEnabledByDefault
        ? null   // force no resolver
        : null
};

if (limitedOptions.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? notFound))
{
    Console.WriteLine($"Unexpectedly resolved: {notFound!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<WeatherForecast> returned false – no metadata available");
}

// --- record used by the demo ---
public record WeatherForecast(string City, int TemperatureF);

